from pathlib import Path
from html import escape as E
import base64
from playwright.sync_api import sync_playwright
P=Path('/mnt/data/Risheh_Corporate_Profile_GitHub')
font=Path('/mnt/data/Ravi-Regular(4).ttf'); bold=Path('/mnt/data/Ravi-Bold(4).ttf')
faces=''
for nm,fp,wt in [('Ravi',font,400),('Ravi',bold,700)]:
 faces+=f"@font-face{{font-family:'{nm}';src:url(data:font/ttf;base64,{base64.b64encode(fp.read_bytes()).decode()}) format('truetype');font-weight:{wt}}}"
css='''@page{size:A4;margin:0}*{box-sizing:border-box}html,body{margin:0;padding:0;background:white;color:#182c28;font-family:Arial,'Helvetica Neue',sans-serif}'''+faces+'''
.page{width:210mm;height:297mm;position:relative;overflow:hidden;page-break-after:always;padding:22mm 21mm 20mm;background:#f7f8f4}.top{font:600 9px Arial;letter-spacing:2px;text-transform:uppercase;display:flex;justify-content:space-between;color:#607b6c;border-bottom:1px solid #c8d4c9;padding-bottom:5mm}.foot{position:absolute;bottom:13mm;left:21mm;right:21mm;display:flex;justify-content:space-between;font:9px Arial;letter-spacing:.8px;color:#65776b;border-top:1px solid #c8d4c9;padding-top:4mm}.eyebrow{font:700 11px Arial;letter-spacing:2.8px;color:#6d8877;text-transform:uppercase;margin-top:20mm;margin-bottom:7mm}h1{font-size:43px;line-height:1.03;letter-spacing:-2.2px;font-weight:700;margin:0 0 10mm;max-width:168mm;color:#153f32}h2{font-size:29px;line-height:1.12;letter-spacing:-1px;margin:0 0 7mm;color:#153f32}h3{font-size:17px;margin:0 0 5mm;color:#174a3a}p{font-size:14.1px;line-height:1.72;margin:0 0 6mm;max-width:167mm;color:#364b42}.lead{font-size:19px;line-height:1.53;letter-spacing:-.3px;color:#203b32}.large{font-size:23px;line-height:1.43;letter-spacing:-.65px}.label{font:700 10px Arial;letter-spacing:2px;text-transform:uppercase;color:#5c8470}.divider{height:2px;width:45mm;background:#4a876b;margin:11mm 0}.muted{color:#6b7f73}.cover{background:#103e32;color:white}.cover h1{font-size:68px;letter-spacing:-3px;color:white;margin-top:32mm;max-width:150mm}.cover p{color:#e3eee5}.cover .top,.cover .foot{color:#b8d4c5;border-color:#487563}.cover .eyebrow{color:#c0d9c5}.circle{width:170mm;height:170mm;border:1px solid #698f78;border-radius:50%;position:absolute;right:-80mm;bottom:-60mm;opacity:.75}.circle:before{content:'';width:110mm;height:110mm;position:absolute;left:25mm;top:25mm;border:1px solid #698f78;border-radius:50%}.circle:after{content:'';width:50mm;height:50mm;position:absolute;left:55mm;top:55mm;border:1px solid #698f78;border-radius:50%}.dark{background:#153e33;color:white}.dark .top,.dark .foot{color:#bdd5c5;border-color:#587967}.dark h1,.dark h2,.dark p,.dark h3{color:white}.dark .eyebrow,.dark .label{color:#b7d1c2}.kicker-number{font-size:132px;line-height:1;font-weight:700;letter-spacing:-8px;color:#dce7de;margin:8mm 0 8mm}.dark .kicker-number{color:#396556}.hero-rule{border-top:1px solid #cbd8ce;padding-top:8mm;margin-top:8mm}.quote{margin-top:16mm;font-size:30px;line-height:1.3;font-weight:700;letter-spacing:-1px;color:#174a3a}.two{display:grid;grid-template-columns:1fr 1fr;gap:10mm;margin-top:10mm}.tile{border-top:2px solid #174a3a;padding-top:7mm}.tile p{font-size:12px;line-height:1.65}.metric{font:700 15px Arial;letter-spacing:1px;color:#174a3a;margin-bottom:5mm}.project{background:#e8efe8;padding:9mm 10mm;margin-top:13mm;border-left:4px solid #1d644b}.project p{font-size:12.5px;line-height:1.7;margin:4mm 0}.project .label{font-size:9px}.notice{font-size:11px;color:#587362;border-top:1px solid #bfd1c1;padding-top:5mm;margin-top:12mm}.sector{background:#143e33}.sector .eyebrow{color:#c4dcca}.sector h1{color:#fff}.sector .lead,.sector p{color:#e1eee5}.sector .top,.sector .foot{color:#bed8c7;border-color:#527b65}.sector .big-num{position:absolute;bottom:25mm;right:16mm;color:#4e7b64;font-size:145px;line-height:1;font-weight:700;opacity:.33}.sectortag{color:#b7d4c3;font:700 11px Arial;letter-spacing:2px;text-transform:uppercase}.grid7{display:grid;grid-template-columns:1fr 1fr;gap:7mm;margin-top:12mm}.grid7 div{padding:7mm;border:1px solid #c5d5c7;background:white;font-size:14px;font-weight:700;color:#174a3a}.grid7 span{display:block;font:11px Arial;color:#627769;margin-top:3mm}.line{width:100%;height:1px;background:#a9bbaa;margin:8mm 0}.ravi{font-family:Ravi;direction:rtl}a{color:inherit;text-decoration:none}.mini{font-size:11px}.pill{display:inline-block;border:1px solid #93b09b;padding:2.5mm 4mm;font:700 10px Arial;color:#174a3a;margin:4mm 3mm 0 0}.fullbleed{background:#103e32}.closing h1{font-size:54px}.link{word-break:break-word;font-size:10px;color:#456b58}
'''
sections=[]
def pg(body,cl=''):
 i=len(sections)+1
 sections.append(f'<section class="page {cl}"><div class="top"><span>RISHEH  /  CORPORATE PROFILE</span><span>2026</span></div>{body}<div class="foot"><span>BUILDING CONNECTED DIGITAL SYSTEMS</span><span>{i:02d}</span></div></section>')
def paras(*ss):return ''.join(f'<p>{E(s)}</p>' for s in ss)
pg('''<div class="eyebrow">COMPANY PROFILE & INDUSTRY SOLUTIONS</div><h1>Growth<br>is engineered.</h1><div class="divider"></div><p class="large">Technology, design and intelligence—built around the way businesses actually work.</p><p style="margin-top:29mm;font-weight:700;letter-spacing:2px">RISHEH</p><p class="ravi" style="font-size:18px;color:#cadfcf">ریشه · معماری رشد پایدار</p><div class="circle"></div>''','cover')
pg('<div class="eyebrow">01 / The belief</div><h1>More technology does not automatically mean more progress.</h1><p class="lead">Businesses have more software, channels and data than ever before. Yet the work often remains fragmented.</p>'+paras('A customer submits a request on a website. Someone transfers it to a spreadsheet. A team discusses it in a chat. A manager checks another dashboard to find out what happened. Each tool may work in isolation; the business system does not.','This is the gap Risheh aims to close. We bring product thinking, engineering, automation and growth together so the digital experience supports the operational reality behind it.')+'<p class="quote">We do not believe in accidental growth.</p>')
pg('<div class="eyebrow">02 / Our role</div><h1>Not another vendor. A partner in building.</h1><p class="lead">Risheh approaches digital transformation as a design and engineering challenge—not a shopping list of features.</p>'+paras('We start with people and processes: what a customer is trying to accomplish, what a team needs to deliver, where information gets lost, and which constraints genuinely shape the solution. From there, we define the right product scope, architecture, experience and operating model.','Sometimes the right answer is a focused website. In other cases it is a multi-role platform, a reliable integration between existing services, a specialized AI workflow, or a carefully staged modernization program. The choice should follow the problem—not the fashion of the moment.')+'<div class="divider"></div><p class="large">Discover the system. Design the experience. Engineer the change.</p>')
pg('<div class="eyebrow">03 / The approach</div><h1>One business problem.<br>Several disciplines.<br>One coherent direction.</h1><div class="two">'+''.join(f'<div class="tile"><div class="label">{h}</div><p>{d}</p></div>' for h,d in [('DISCOVERY','Business analysis, product discovery, market context and measurable outcomes.'),('DESIGN','Information architecture, user experience, identity and product systems.'),('ENGINEERING','Web applications, platforms, APIs and dependable foundations.'),('CONNECTION','Workflow automation, integration, structured data and AI assistance.')])+'</div><p class="notice">The mix is project-specific. No single technology stack or delivery model is imposed on every client.</p>')
pg('<div class="eyebrow">04 / Industry focus</div><h1>We organize our work around industries, not buzzwords.</h1><p class="lead">The same technology can solve very different problems in a school, a clinic, a workplace or an online business.</p><div class="grid7">'+''.join(f'<div>{h}<span>{d}</span></div>' for h,d in [('Education','School operations & learning'),('Health & care','Trusted service journeys'),('Work & operations','Connected teams & knowledge'),('AI infrastructure','Responsible agents & control'),('Career technology','Discovery, matching & alerts'),('Digital commerce','Product data & purchasing'),('Professional services','Clear services & client journeys')])+'</div><p class="notice">The following profiles distinguish repository-backed projects from broader solution capabilities. Product maturity and production claims are not inferred from README feature lists.</p>')
industries=[
('01','EDUCATION','A school is an ecosystem of people, not a collection of forms.','A principal needs a coherent operational view. Teachers need a reliable flow for instruction and assessment. Parents need relevant information about their children without exposure to other students’ records. Children need experiences appropriate to their age. When these requirements are distributed across disconnected systems, administrative effort grows and context disappears.','We design educational platforms around roles, permissions, school configuration and clear daily workflows. The objective is to give each participant an appropriate view of the same trusted underlying system.','Hamyar School / MySchoolPlatform','A multi-tenant School Operating System described in the repository with school management domains, role-scoped experiences, configurable modules and an elementary experience layer. Its architecture emphasizes tenant isolation and a shared core rather than separate forks for individual schools.','https://github.com/mahamirmh/myschoolplatform','Repository-backed engineering case; rollout status varies by module and environment.'),
('02','HEALTH & CARE','In sensitive services, clarity is part of trust.','When a person looks for counseling or a specialist service, they may not know which option is appropriate. The digital experience must help them discover reliable information and take the next step without fabricated endorsements, ambiguous pathways or promises of outcomes. Editorial structure, accessible navigation and data protection matter as much as visual polish.','We connect service discovery, educational content, consultation requests and operational handoffs. Human professional judgment remains central; software supports the journey without pretending to replace clinical expertise.','Entekhab Platform','A Persian-language PWA documented with service discovery, an editorial content hub, specialist information and a structured consultation request journey. The repository explicitly favors source-backed content and avoids invented ratings or profiles.','https://github.com/mahamirmh/Entekhab-Platform','No therapeutic outcome, medical effectiveness or full production verification is claimed.'),
('03','WORK & OPERATIONS','Every disconnected decision creates operational friction.','Inside teams, a decision can start in a conversation, become a task somewhere else, affect a repository and end up as a document nobody can find. A workplace needs more than another dashboard: it needs continuity between communication, responsibility, execution and organizational knowledge.','Our approach combines collaboration, task context, permissions, documentation and engineering integrations in a coherent workspace. This is not about centralizing everything blindly; it is about making critical work traceable and useful.','Risheh Core','Risheh’s internal workspace, documented across communication, projects, tasks, knowledge, engineering rooms and integrations. Its purpose is to preserve context across the lifecycle from conversation to implementation.','https://github.com/mahamirmh/Risheh-Core','Internal product. Confidential screens, user data and internal documents are intentionally excluded.'),
('04','AI & AGENT INFRASTRUCTURE','An agent is only useful when its actions can be governed.','Connecting an AI model to business tools introduces operational questions: What can it access? Which actions need approval? How can a repeated request be handled safely? What evidence exists after execution? These are architecture problems, not prompt-writing details.','We treat agent identity, capability contracts, policy boundaries, auditable execution and human oversight as core parts of AI engineering. The business domain retains ownership of its source of truth while shared infrastructure handles reusable execution concerns.','Risheh AI Platform','A shared AI foundation with documented capability routing, versioned contracts, execution persistence, idempotency and audit concepts. The README differentiates reference implementations from production-ready multi-tenant infrastructure.','https://github.com/mahamirmh/Risheh-AI-Platform','Some components are reference or local implementations—not a claim of production enterprise deployment.'),
('05','CAREER TECHNOLOGY','The value is not more vacancies. It is better decisions.','Specialized career journeys become difficult when opportunities are scattered and eligibility is hard to assess. Users must compare requirements, understand missing evidence, track applications and receive relevant alerts. Automated systems should reduce noise while keeping their reasoning inspectable.','We combine data ingestion, structured classification, explainable matching, scheduled processing and communication workflows for domain-specific services. Accuracy and source integrity must be addressed alongside convenience.','Risheh NHS JobBot','A Django, PostgreSQL, Redis, Celery and Telegram-based project for medical job discovery, matching, application readiness and alerts. Its README describes an explainable workflow rather than a generic vacancy notification bot.','https://github.com/mahamirmh/rishehjobnhsbot','Repository-described functionality; independently verified employment outcomes are not claimed.'),
('06','DIGITAL COMMERCE','A smooth storefront needs disciplined operations behind it.','A customer sees a product page and checkout. The business sees inventory, catalog quality, channel integration, order state, fulfillment and support. Weak links behind the scenes eventually become customer-facing friction, especially when catalog size and sales channels grow.','Risheh can support commerce experience design, WooCommerce customization, product-data modeling, catalog cleanup, operational integrations and tailored shopping journeys. We choose between packaged systems and custom platforms according to the operational context.','Commerce Solutions','A capability area spanning e-commerce engineering, inventory and product data, workflow automation and conversion design. Named client case studies should be added only with publication approval and supporting evidence.','https://github.com/mahamirmh','Capability area; no client metrics or fabricated project results included.'),
('07','PROFESSIONAL SERVICES','Trust becomes action when the next step is clear.','For a legal practice, real-estate business, consultancy or specialist firm, the online journey often begins before a conversation. People need to understand a service, evaluate credibility and confidently submit a request. Complex navigation and disconnected lead handling undermine that journey.','Our work connects content strategy, landing pages, information architecture, inquiry flows, CRM handoff and operational dashboards, designed with each industry’s regulatory and privacy boundaries in mind.','Specialist Service Platforms','A solution category for service businesses that need more than a brochure website. Individual client names, screenshots and delivery claims require case-by-case publication clearance.','https://github.com/mahamirmh','Capability area, not a claim that every named vertical has a completed public case study.')]
for num,sector,headline,problem,solution,proj,detail,url,caveat in industries:
 pg(f'<div class="eyebrow">INDUSTRY {num} / {E(sector)}</div><h1>{E(headline)}</h1><p class="lead">{E(problem)}</p><div class="divider"></div><div class="label">HOW RISHEH APPROACHES IT</div><p style="margin-top:7mm">{E(solution)}</p><div class="big-num">{num}</div>','sector')
 pg(f'<div class="eyebrow">SELECTED WORK / {E(sector)}</div><h1>{E(proj)}</h1><p class="lead">{E(detail)}</p><div class="project"><div class="label">SOURCE / PROJECT REFERENCE</div><p class="link">{E(url)}</p><div class="line"></div><div class="label">EVIDENCE & SCOPE NOTE</div><p>{E(caveat)}</p></div><div class="eyebrow">WHY THIS MATTERS</div><p>{E(solution)}</p>')
pg('<div class="eyebrow">05 / Delivery model</div><h1>From ambiguity to a product people can use.</h1>'+''.join(f'<div class="hero-rule"><div class="label">{i:02d} / {h}</div><p>{t}</p></div>' for i,(h,t) in enumerate([('Understand','Explore the business need, audiences, process constraints and measurable success criteria.'),('Frame','Define a clear scope, priorities, architecture choices and delivery assumptions.'),('Design & build','Create useful journeys and engineering foundations; implement capabilities in reviewable increments.'),('Verify','Test quality, permissions, integrations and operational assumptions against agreed acceptance criteria.'),('Deliver & evolve','Document, deploy, transfer knowledge and plan subsequent improvements where agreed.')],1)))
pg('<div class="eyebrow">06 / Engineering principles</div><h1>Quality is what happens after the demo.</h1><p class="lead">A convincing interface matters. So do the parts customers rarely see.</p>'+paras('We design for maintainability, appropriate security controls, sensible access boundaries, controlled releases, useful documentation and evidence-led verification. An architecture should be understandable to the people who will operate it; a product should be adaptable without unnecessary complexity.','These are working principles, not unconditional warranties. Testing scope, operational support, hosting, security requirements and service levels are agreed for each engagement.')+'<div class="two">'+''.join(f'<div class="tile"><h3>{h}</h3><p>{d}</p></div>' for h,d in [('Reliable boundaries','Clear roles, data ownership and integration responsibilities.'),('Designed to evolve','Modular architecture and staged product roadmaps.'),('Operational clarity','Observability, release discipline and documentation.'),('Measured usefulness','Relevant business and user experience indicators.')])+'</div>')
pg('<div class="eyebrow">07 / Ways to work together</div><h1>Different starting points.<br>One commitment to clarity.</h1>'+paras('For some teams, the challenge is defining what should be built. For others, the problem is a legacy system that no longer supports their ambitions. Some need a new digital product; others need to connect systems they already trust.','Risheh works across product discovery, custom development, platform modernization, user experience redesign, automation and integrations, and ongoing improvement under defined agreements. Each engagement should make the scope, responsibilities, deliverables, dependencies and acceptance criteria explicit.')+'<p class="quote">The right scope is the one that moves the business forward.</p>')
pg('<div class="eyebrow">08 / An invitation</div><h1>Let us build what comes next.</h1><p class="lead">Growth does not begin with a feature list. It begins with a clearer understanding of the business you want to become.</p>'+paras('If your teams are navigating fragmented tools, a growing product, changing customer expectations or new opportunities for automation and AI, Risheh can help turn that complexity into a direction that can be designed, engineered and improved.','We believe in technology that earns its place in a business—through better experiences, clearer workflows and systems ready to evolve.')+'<div class="divider"></div><p class="large">RISHEH<br>Growth is engineered.</p><p>rishehcompany.ir</p><p class="mini muted" style="margin-top:12mm">Public company profile · 2026 · Client-specific commitments belong in separate proposals and agreements.</p>','dark closing')
html='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><style>'+css+'</style></head><body>'+''.join(sections)+'</body></html>'
(P/'Risheh_Industry_Profile_EN.html').write_text(html,encoding='utf-8')
with sync_playwright() as pw:
 b=pw.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox']);page=b.new_page();page.set_content(html,wait_until='load');page.evaluate('document.fonts.ready');page.pdf(path=str(P/'Risheh_Industry_Profile_EN.pdf'),print_background=True,prefer_css_page_size=True);b.close()
print('pages',len(sections))
